  hours: [["Now", "sun.max.fill", 24], ["1PM", "sun.max.fill", 25], ["2PM", "cloud.sun.fill", 26], ["3PM", "cloud.sun.fill", 26], ["4PM", "cloud.fill", 24], ["5PM", "cloud.fill", 22]],
