      <hstack alignment="top"><Header big /><spacer /><Summary /></hstack>
      <Hours count={6} />
      <rect color="white" opacity="0.25" frame="max,1" />
      <Days barWidth={wide ? 360 : 110} />
      <spacer />
    </vstack>
  );
}

